import {CARDS as C,REGIONS,PRESETS,DATASET,createGame,act,view,attack,keywords,cardSupported} from '/engine.js';
import {createMotion} from '/motion.js';
import {installDrag} from '/drag.js';
const $=s=>document.querySelector(s),app=$('#app');
const STORE='lor-foundations';
const K={QuickStrike:'快速攻击',Overwhelm:'碾压',Regeneration:'再生',Elusive:'隐密',Challenger:'挑战者',Barrier:'屏障',Tough:'坚忍',Lifesteal:'吸血',Fearsome:'威吓',Ephemeral:'瞬逝',CantBlock:'无法格挡',DoubleStrike:'双重攻击',Frostbite:'凍傷',Stun:'擊暈',Scout:'斥候',LastBreath:'遺願',Fleeting:'飛逝',Burst:'疾速',Fast:'快速',Slow:'慢速'};
const S={fast:'快速',slow:'慢速',burst:'疾速',focus:'專注'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clean=s=>String(s??'').replace(/<[^>]*>/g,'').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&');
const presets=Array.isArray(PRESETS)?PRESETS:Object.entries(PRESETS||{}).map(([id,p])=>({id,...p}));
const regions=Array.isArray(REGIONS)?REGIONS:Object.entries(REGIONS||{}).map(([id,name])=>({id,name:typeof name==='string'?name:name.name}));
const regionName=id=>regions.find(r=>r.id===id)?.name||id;
const collection=Object.entries(C).filter(([,c])=>c.collectible);
const implemented=collection.filter(([id])=>cardSupported(id));
let mode='lobby',g=null,full=null,seat=0,room=null,ready=true,busy=false,curtain=false,polling=false,netError='',sessionEpoch=0;
let selected=null,fixedTargets=[],extraTargets=[],targetGroup=0,replaceUid=null,sacrifices=new Set(),playChoice='attack',discards=new Set(),attackMode=false,attackers=new Set(),challenger=null,challenges={},blocker=null,blocks={},mulligans=new Set();
let modal=null,inspectId=null,backModal=null,query='',regionFilter='',supportFilter='all';
let deckChoices=[presets[0]?.id||'',presets[1]?.id||presets[0]?.id||''],builderDeck=[],builderName='我的基礎套牌',builderError='';
let customDeck=loadCustom();
let reducedMotion=loadMotionPreference(),renderedFrame=null;
const motion=createMotion({root:app,cards:C});
motion.setReduced(reducedMotion);
const drag=installDrag({root:app,getState:()=>({game:g,seat,mine:mine()&&!modal&&g?.phase!=='mulligan',selected,attackMode,curtain,canDrop}),onDrop:handleDrop});
function loadMotionPreference(){try{const value=localStorage.getItem(STORE+'-motion');if(value)return value==='reduced';}catch{}return !!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;}

function loadCustom(){try{const x=JSON.parse(localStorage.getItem('et-deck')||'null');return Array.isArray(x)?{name:'我的基礎套牌',deck:x}:x?.deck?x:null;}catch{return null;}}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3600);}
function art(c){return `<div class="art-fallback" aria-hidden="true">${c.hero?'✦':c.kind==='spell'?'✧':'◇'}</div>${c.art?`<img class="art" src="${esc(c.art)}" loading="lazy" alt="${esc(c.name)}原版插畫" onerror="this.remove()">`:''}`;}
function cardMarkup(h,{unit=false,active=false,chosen=false,targetable=false,catalog=false}={}){
 if(h.hidden)return '<div class="card back"><span>✦</span></div>';
 const c=C[h.card];if(!c)return '';
 const u=unit?h:null,kw=u?keywords(u,g):(c.kw||[]),can=cardSupported(h.card);
 const attr=catalog?`data-inspect="${esc(h.card)}"`:`data-${unit?'unit':'hand'}="${esc(h.uid)}"`;
 const currentCost=h.cost??c.cost;
 return `<button class="card ${unit?'unit':''} ${active?'selected':''} ${chosen?'chosen':''} ${targetable?'targetable':''} ${c.hero?'hero':''} ${u?.stunned?'stunned':''} ${discards.has(h.uid)?'discard-selected':''}" ${attr} title="${esc(c.name+' · '+clean(c.text))}" aria-label="${esc(c.name)}，${currentCost}費，${esc(clean(c.text))}"><div class="card-art">${art(c)}<span class="cost">${currentCost}</span>${c.hero?'<span class="rarity">✦</span>':''}${discards.has(h.uid)?'<span class="discard-tag">棄置</span>':''}${catalog?`<span class="support-badge ${can?'yes':''}">${can?'可對戰':'待實現'}</span>`:''}</div><div class="card-name">${u?.level?'✦ ':''}${esc(c.name)}</div>${unit?`<div class="unit-keywords">${u?.stunned?'擊暈 · ':''}${u?.frozen?'凍傷 · ':''}${kw.map(k=>K[k]||k).join(' · ')||'單位'}</div>`:`<div class="card-text">${c.kind==='spell'?`<span class="speed">${S[c.speed]||''}</span> `:''}${esc(clean(c.text)||'—')}</div>`}${c.kind==='unit'?`<div class="stats"><span class="atk">${u?attack(u,g):c.atk}</span><span class="hp ${u&&u.hp<u.maxHp?'hurt':''}">${u?u.hp:c.hp}</span></div>`:`<div class="spell-mark">${c.kind==='skill'?'技能':(S[c.speed]||'')+'法術'}</div>`}</button>`;
}
function header(){return `<header><button class="brand" data-action="home"><span class="brand-mark">✦</span><span>LEGENDS <small>OF RUNETERRA</small></span></button><div class="header-right"><span class="version">非官方 · 基礎卡池復現</span><button class="text-btn" data-action="deckbuilder">組建套牌</button><button class="text-btn" data-action="catalog">卡牌圖鑑</button><button class="text-btn motion-toggle" data-action="motion" aria-pressed="${reducedMotion}" title="切換簡化動畫">動畫：${reducedMotion?'簡化':'完整'}</button><button class="text-btn" data-action="rules">玩法指南 ↗</button></div></header>`;}
function chosenDeck(n){if(deckChoices[n]==='custom'&&customDeck)return customDeck.deck;return presets.find(p=>p.id===deckChoices[n])?.deck||presets[n%presets.length]?.deck||[];}
function chosenName(n){return deckChoices[n]==='custom'?customDeck?.name:presets.find(p=>p.id===deckChoices[n])?.name;}
function deckSelect(n){return `<label class="deck-select"><span>${n===0?'你的套牌 / 玩家一':'同屏對手 / 玩家二'}</span><select data-deck-seat="${n}" aria-label="${n===0?'玩家一':'玩家二'}套牌">${presets.map(p=>`<option value="${esc(p.id)}" ${deckChoices[n]===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}${customDeck?`<option value="custom" ${deckChoices[n]==='custom'?'selected':''}>${esc(customDeck.name)} · 自組套牌</option>`:''}</select></label>`;}
function showcase(name){const item=Object.entries(C).find(([,c])=>c.nameEn===name&&c.collectible)||collection.find(([,c])=>c.hero);return item?cardMarkup({card:item[0],uid:'showcase-'+name},{catalog:true}):'';}
function lobby(){return `${header()}<main class="lobby"><div class="lobby-copy"><div class="eyebrow"><span></span> FOUNDATIONS · PVP FAN PROTOTYPE</div><h1>你的下一步，<br><span>決定符文大地。</span></h1><p class="intro">原版英雄、卡牌與插畫。從基礎卡池出發，<br>在交替行動與攻防之間，打出你的策略。</p><div class="deck-selects">${deckSelect(0)}${deckSelect(1)}</div><div class="lobby-actions"><button class="primary" data-action="local">同屏雙人對戰 <span>→</span></button><button class="secondary" data-action="create">建立連線房間</button></div><form id="join-form" class="join"><input id="room-code" maxlength="8" placeholder="輸入 8 位房間碼" aria-label="房間碼" autocomplete="off" spellcheck="false"><button type="submit">加入房間 ↗</button></form><div class="resume">${sessionStorage.getItem(STORE+'-local')?'<button class="text-btn" data-action="resume-local">繼續同屏對局 ↗</button>':''}${sessionStorage.getItem(STORE+'-room')?'<button class="text-btn" data-action="resume-online">重新連線 ↗</button>':''}</div><div class="lobby-notes"><span><b>${collection.length}</b> 張基礎卡牌</span><span><b>${implemented.length}</b> 張可用於對戰</span><span><b>40</b> 張自組套牌</span></div></div><div class="feature-cards"><div class="showcase demacia">${showcase('Garen')}<span>蒂瑪西亞 <small>為了榮耀與正義</small></span></div><div class="versus">✦<small>VS</small></div><div class="showcase noxus">${showcase('Darius')}<span>諾克薩斯 <small>以力量決定命運</small></span></div><div class="showcase-caption">英雄登場 · 原版基礎卡池</div></div><footer><span>EMBER & TIDE PROJECT · 非官方同人研究原型</span><span>官方卡牌資源 © Riot Games · 引擎原始碼開源</span></footer></main>`;}
function mine(){return !!g&&g.priority===seat&&ready&&g.winner===null&&!curtain&&!busy;}
function playerName(p){return g?.players[p]?.name||chosenName(p)||'玩家 '+(p+1);}
function selectedCard(){return g?.players[seat].hand.find(h=>h.uid===selected);}
function discardSpec(){const c=C[selectedCard()?.card];return c?.discard&&typeof c.discard==='object'?c.discard:null;}
function discardCount(){const d=discardSpec();return d?.requireMaximum?Math.min(d.max,g.players[seat].hand.length-1):d?.min||0;}
const targetLabel={any:'單位或主堡',unit:'任意單位',follower:'隨從',enemy:'敵軍或敵方主堡',enemyUnit:'敵軍',enemyFollower:'敵方隨從',ally:'友軍',allyAny:'友軍或己方主堡',allyDamaged:'受傷友軍',allyHand:'手牌',allyHandUnit:'手牌中的單位',cardHand:'手牌',stack:'回應鏈中的法術或技能'};
function targetPlan(){const c=C[selectedCard()?.card];if(!c)return [];const fixed=(c.targets||[c.target,c.target2,c.target3]).map((type,i)=>({type,slot:i,min:c.targetOptional?0:1,max:1,fixed:true})).filter(x=>x.type&&x.type!=='none');if(c.targetCount)fixed.push({...c.targetCount,fixed:false,min:c.targetCount.min??0,max:c.targetCount.max??1});return fixed;}
function groupIds(group){return group.fixed?(fixedTargets[group.slot]?[fixedTargets[group.slot]]:[]):extraTargets;}
function sacrificeCount(){return C[selectedCard()?.card]?.sacrifice?.count||0;}
function replacementAvailable(){return C[selectedCard()?.card]?.kind==='unit'&&g.players[seat].board.length>=6;}
function replacementNeeded(){const c=C[selectedCard()?.card];return replacementAvailable()&&!c.sacrifice?.count&&!c.freesBoardSlot;}
function choosingReplacement(){return replacementAvailable()&&(targetGroup===-1||replacementNeeded()&&!replaceUid);}
function choosingSacrifice(){return sacrificeCount()>0&&sacrifices.size<sacrificeCount();}
function activeGroup(){const plan=targetPlan();return plan[Math.min(targetGroup,Math.max(0,plan.length-1))];}
function activeTarget(){return choosingSacrifice()?'sacrifice':choosingReplacement()?'replace':activeGroup()?.type||null;}
function selectedTargetIds(){return [...fixedTargets.filter(Boolean),...extraTargets];}
function targetName(id){if(id==='core0'||id==='core1')return playerName(Number(id[4]))+'的主堡';const item=g?.stack.find(x=>x.uid===id);if(item)return C[item.displayId||item.cid]?.name||'法術／技能';const h=g?.players.flatMap(s=>[...s.board,...s.hand]).find(x=>x.uid===id);return C[h?.card]?.name||id;}
function targetAllowed(type,p,u,isCore=false){
 if(!type||type==='none')return false;
 if(type==='any')return true;
 if(type==='unit')return !isCore;
 if(type==='follower')return !isCore&&!C[u.card].hero;
 if(type==='enemy')return p!==seat;
 if(type==='enemyUnit')return p!==seat&&!isCore;
 if(type==='enemyFollower')return p!==seat&&!isCore&&!C[u.card].hero;
 if(type==='ally'||type==='sacrifice'||type==='replace')return p===seat&&!isCore;
 if(type==='allyAny')return p===seat;
 if(type==='allyDamaged')return p===seat&&!isCore&&u.hp<u.maxHp;
 return false;
}
function targetSelected(id){return selectedTargetIds().includes(id)||sacrifices.has(id)||replaceUid===id;}
function canTarget(p,u=null,isCore=false){if(!selectedCard()||!mine()||g.choice)return false;const id=isCore?'core'+p:u?.uid;if(sacrifices.has(id)||replaceUid===id)return true;if(['sacrifice','replace'].includes(activeTarget()))return targetAllowed(activeTarget(),p,u,isCore);return targetAllowed(activeTarget(),p,u,isCore)&&!sacrifices.has(id);}
function handTargetable(h){return !!h&&!!selectedCard()&&mine()&&!g.choice&&h.uid!==selected&&(['allyHand','cardHand'].includes(activeTarget())||activeTarget()==='allyHandUnit'&&C[h.card]?.kind==='unit');}
function groupCandidates(group){if(!g)return [];let ids=[];if(group.type==='stack')ids=g.stack.map(x=>x.uid).filter(Boolean);else if(['allyHand','cardHand','allyHandUnit'].includes(group.type))ids=g.players[seat].hand.filter(h=>h.uid!==selected&&(group.type!=='allyHandUnit'||C[h.card]?.kind==='unit')).map(h=>h.uid);else{for(let p=0;p<2;p++){if(targetAllowed(group.type,p,null,true))ids.push('core'+p);for(const u of g.players[p].board)if(u.hp>0&&targetAllowed(group.type,p,u))ids.push(u.uid);}if(group.includeSelf&&selected&&!group.fixed)ids.push(selected);}return ids.filter(id=>id!==replaceUid&&!sacrifices.has(id)&&(!group.fixed?!fixedTargets.includes(id):true));}
function groupMinimum(group){return group.requireMaximum?Math.min(group.max,groupCandidates(group).length):group.min;}
function targetReady(){return (!discardSpec()||(discards.size>=discardCount()&&discards.size<=discardSpec().max))&&(!replacementNeeded()||!!replaceUid)&&sacrifices.size===sacrificeCount()&&targetPlan().every(group=>{const n=groupIds(group).length;return n>=groupMinimum(group)&&n<=group.max&&groupIds(group).every(id=>id!==replaceUid&&!sacrifices.has(id));});}
function pickTarget(id){if(!mine())return;if(activeTarget()==='replace'||replaceUid===id){if(sacrifices.has(id)||selectedTargetIds().includes(id)){toast('取代的單位不能同時作為犧牲代價或卡牌目標');return;}if(!g.players[seat].board.some(u=>u.uid===id&&u.hp>0)){toast('請選擇己方場上單位');return;}replaceUid=replaceUid===id?null:id;if(replaceUid)targetGroup=0;render();return;}if(activeTarget()==='sacrifice'){if(replaceUid===id||selectedTargetIds().includes(id)){toast('犧牲代價不能同時作為取代單位或卡牌目標');return;}if(!g.players[seat].board.some(u=>u.uid===id&&u.hp>0)){toast('請選擇己方場上單位');return;}if(sacrifices.has(id))sacrifices.delete(id);else if(sacrifices.size<sacrificeCount())sacrifices.add(id);render();return;}if(sacrifices.has(id)){sacrifices.delete(id);render();return;}const group=activeGroup();if(!group)return;if(!groupCandidates(group).includes(id)&&!groupIds(group).includes(id)){toast('這個目標無法選擇');return;}if(group.fixed){if(fixedTargets[group.slot]===id)fixedTargets[group.slot]=null;else{if(selectedTargetIds().includes(id)){toast('請選擇不同的目標');return;}fixedTargets[group.slot]=id;if(targetGroup<targetPlan().length-1)targetGroup++;}}else{const n=extraTargets.indexOf(id);if(n>=0)extraTargets.splice(n,1);else{if(extraTargets.length>=group.max){toast('最多選擇 '+group.max+' 個目標');return;}if(group.distinct!==false&&selectedTargetIds().includes(id)){toast('請選擇不同的目標');return;}extraTargets.push(id);}}render();}
function selectionMarkup(){const plan=targetPlan();let html='';if(replacementAvailable())html+=`<div class="target-group replace-group ${choosingReplacement()?'current':''}"><button class="target-group-heading" data-replace-mode>取代友軍 · ${replaceUid?'1':'0'} / ${replacementNeeded()?'1':'0–1'}</button><div class="target-chips">${replaceUid?`<button data-remove-replace>${esc(targetName(replaceUid))} ×</button>`:'<small>抹除一個友軍騰出位置；不觸發死亡。</small>'}</div></div>`;if(sacrificeCount())html+=`<div class="target-group sacrifice-group ${choosingSacrifice()?'current':''}"><span>犧牲代價 ${sacrifices.size} / ${sacrificeCount()}</span><div class="target-chips">${[...sacrifices].map(id=>`<button data-remove-sacrifice="${esc(id)}">${esc(targetName(id))} ×</button>`).join('')||'<small>點選己方場上單位</small>'}</div></div>`;return html+plan.map((group,i)=>`<div class="target-group ${i===targetGroup&&!choosingSacrifice()?'current':''}"><button class="target-group-heading" data-target-group="${i}">${group.fixed?'目標 '+(i+1):'追加目標'} · ${esc(group.label||targetLabel[group.type]||group.type)} <span>${groupIds(group).length} / ${group.requireMaximum?groupMinimum(group):group.min===group.max?group.max:group.min+'–'+group.max}</span></button><div class="target-chips">${groupIds(group).map((id,n)=>`<button data-remove-target="${esc(id)}" data-remove-group="${i}">${group.fixed?'':(n+1)+'. '}${esc(targetName(id))} ×</button>`).join('')||'<small>'+(group.min===0?'可不選；點選高亮目標加入':'點選高亮目標')+'</small>'}${group.includeSelf&&!group.fixed&&!extraTargets.includes(selected)?'<button class="self-target" data-self-target>＋ 此卡自身</button>':''}</div></div>`).join('');}
function playerBar(p,opponent){const s=g.players[p];return `<div class="player-bar ${opponent?'opponent':'self'}"><button data-core="${p}" class="core ${p===0?'warm':''} ${canTarget(p,null,true)?'targetable':''} ${targetSelected('core'+p)?'chosen':''}" aria-label="${esc(playerName(p))}主堡，${s.hp}生命"><span>◈</span><strong>${s.hp}</strong></button><div class="player-info"><strong>${esc(playerName(p))} ${p===seat?'<small>你</small>':''}</strong><span>${(s.regions||[]).map(regionName).map(esc).join(' · ')||'基礎套牌'}</span></div><div class="resources"><div class="mana-dots">${Array.from({length:s.maxMana??Math.min(10,g.round)},(_,i)=>`<i class="${i<s.mana?'on':''}"></i>`).join('')}</div><span><b>${s.mana}</b> / ${s.maxMana??Math.min(10,g.round)} 法力 <em>${'◆'.repeat(s.bank)}${'◇'.repeat(Math.max(0,3-s.bank))}</em> 法術法力</span></div><div class="deck-info">▱ ${s.deckCount}<small>牌庫</small></div><div class="token ${(g.tokens?.[p]??(g.attacker===p&&g.token))?'lit':''}">${(g.tokens?.[p]??(g.attacker===p&&g.token))?'⚔':'◌'}<small>${(g.tokens?.[p]??(g.attacker===p&&g.token))?'攻擊令牌':'防守'}</small></div></div>`;}
function boardRow(p){const s=g.players[p];return `<div data-board="${p}" class="board-row ${p===seat?'own-board':'opponent-board'}">${s.board.map(u=>`<div class="board-unit ${g.combat?.lanes.some(l=>l.attacker===u.uid||l.blocker===u.uid)?'committed-unit':''}">${cardMarkup(u,{unit:true,active:blocker===u.uid||challenger===u.uid,chosen:targetSelected(u.uid)||attackers.has(u.uid)||Object.values(blocks).includes(u.uid)||Object.values(challenges).includes(u.uid),targetable:canTarget(p,u)||!!(attackMode&&challenger&&p!==seat&&!u.stunned)})}${challenges[u.uid]?`<span class="challenge-tag">挑戰 ${esc(C[g.players[1-p].board.find(x=>x.uid===challenges[u.uid])?.card]?.name||'')}</span>`:''}</div>`).join('')}${Array.from({length:Math.max(0,6-s.board.length)},()=>'<div class="empty-slot"><span>◇</span></div>').join('')}</div>`;}
function phaseName(){if(g.choice)return g.choice.p===seat?'挑選卡牌':'對手正在挑選';if(!ready)return '等待對手加入';if(g.winner!==null)return '對局結束';if(g.phase==='mulligan')return '調整起手牌';if(g.phase==='block')return '安排格擋';if(g.stack.length)return '法術回應';if(g.phase==='combat')return '戰鬥回應';return '行動階段';}
function hint(){if(!ready)return '複製房間碼給另一位玩家。對方加入後即可開始換牌。';if(g.choice)return g.choice.p===seat?'從展示的卡牌中選擇一張，繼續結算。':'等待對手完成卡牌選擇。';if(!mine())return playerName(g.priority)+'正在行動。你可以查看場上卡牌。';if(g.phase==='mulligan')return '選擇想換掉的起手牌，再確認。可以全部保留。';if(selectedCard()){const c=C[selectedCard().card];if(discardSpec()&&discards.size<discardCount())return '此卡需要棄牌：點擊其他手牌，選擇 '+discardCount()+' 張要棄置的牌。';if(choosingReplacement())return '戰場已滿。點擊一個己方單位將它抹除，騰出召喚位置；不觸發死亡或遺願。';if(choosingSacrifice())return '點擊己方場上單位，選擇 '+sacrificeCount()+' 個犧牲代價。出牌時才支付代價。';const group=activeGroup();if(group)return '點選'+(targetLabel[group.type]||'高亮目標')+'加入選擇。可點選已選目標取消；準備好後點擊「確認出牌」。';if(c.options)return '先選擇卡牌效果，再點擊出牌。';}if(attackMode)return challenger?'挑戰者已選取：點擊一個敵軍，將它拉入這條戰線。':'點擊己方單位選擇攻擊者。再次點擊挑戰者可選擇敵軍。';if(g.phase==='block')return '先點己方單位，再點戰線分配格擋。也可先使用快速或疾速法術。';if(g.stack.length)return '快速法術可加入回應鏈；疾速法術立即生效。對手讓過後，由後向前結算。';if(g.phase==='combat')return '格擋已確定。你可以回應防守方的法術；讓過後結算回應鏈與戰鬥。';return '召喚單位、施放法術，或選擇單位攻擊。雙方連續讓過，進入下一輪。';}
function combatPortrait(u,role){if(!u)return `<span class="combat-vacancy">${role==='blocker'?'＋':'◇'}</span>`;return `<span class="combat-portrait ${role}" data-combat-unit="${esc(u.uid)}"><img src="${esc(C[u.card].art)}" alt="${esc(C[u.card].name)}"><small>${attack(u,g)}<i>│</i>${u.hp}</small></span>`;}
function arena(){
 if(!g.combat)return `<div class="arena-empty"><span class="line"></span><span>✦</span><span class="round-label">${g.phase==='mulligan'?'MULLIGAN':'ROUND '+String(g.round).padStart(2,'0')}</span><span>✦</span><span class="line"></span></div>`;
 return `<div class="combat-lanes">${g.combat.lanes.map((l,i)=>{const a=g.players[g.combat.p].board.find(u=>u.uid===l.attacker),bid=g.phase==='block'?(blocks[l.attacker]||l.blocker):l.blocker,b=g.players[1-g.combat.p].board.find(u=>u.uid===bid),top=g.combat.p===seat?b:a,bottom=g.combat.p===seat?a:b;return `<button class="lane ${blocker?'assignable':''} ${b?'is-blocked':''}" data-lane="${esc(l.attacker)}" aria-label="戰線 ${i+1}：${esc(a?C[a.card].name:'攻擊者已離場')}，${esc(b?C[b.card].name:'未格擋')}">${combatPortrait(top,top===a?'attacker':'blocker')}<span class="combat-swords">${l.challenged?'⛓':'⚔'}</span>${combatPortrait(bottom,bottom===a?'attacker':'blocker')}<span class="lane-caption">${b?'已格擋':'未格擋'}</span></button>`;}).join('')}</div>`;
}
function detail(){const h=selectedCard();if(!h)return `<div class="detail-placeholder"><span>✦</span><p>選擇一張手牌</p><small>右鍵點擊任意卡牌可查看原卡</small></div>`;const c=C[h.card];return `<div class="detail-card">${cardMarkup(h)}<button class="text-btn" data-inspect="${esc(h.card)}">查看完整原卡 ↗</button><p>${esc(clean(c.text))}${c.levelText?'<br><span class="gold">升級：</span>'+esc(clean(c.levelText)):''}</p></div>`;}
function actionPanel(){const h=selectedCard(),c=h?C[h.card]:null;let actions='';
 if(g.winner!==null)actions=`<div class="victory">${g.winner==='draw'?'平局':esc(playerName(g.winner))+'獲勝'}<span>這場戰鬥，已成為傳說。</span></div><button class="primary wide" data-action="leave">返回大廳</button>`;
 else if(g.choice)actions=`<p class="choice-wait">${g.choice.p===seat?'請從展示的卡牌中選擇一張。':'等待對手選擇卡牌…'}</p>`;
 else if(g.phase==='mulligan')actions=`<button class="primary wide" data-action="mulligan" ${!mine()?'disabled':''}>${mulligans.size?'更換 '+mulligans.size+' 張牌':'保留全部起手牌'} →</button>`;
 else {
 if(c){actions+=selectionMarkup();if(discardSpec())actions+=`<div class="discard-instruction">棄置手牌 ${discards.size} / ${discardSpec().requireMaximum?discardCount():discardSpec().min===discardSpec().max?discardSpec().max:discardSpec().min+'–'+discardSpec().max}<small>點擊其他手牌選取或取消</small></div>`;if(c.options)actions+=`<label class="choice-label">選擇效果<select id="play-choice">${c.options.map((x,i)=>`<option value="${esc(typeof x==='string'?x:x.id)}" ${playChoice===(typeof x==='string'?x:x.id)?'selected':''}>${esc(typeof x==='string'?x:x.name||x.label||'選項 '+(i+1))}</option>`).join('')}</select></label>`;actions+=`<button class="primary wide" data-action="play" ${!mine()||!targetReady()?'disabled':''}>${targetPlan().length||sacrificeCount()?'確認出牌':c.kind==='unit'?'召喚單位':'施放法術'} <small>${h.cost??c.cost} 法力</small></button><button class="text-btn wide" data-action="cancel">取消選擇</button>`;}
 if(g.phase==='block')actions+=`<button class="primary wide" data-action="block" ${!mine()?'disabled':''}>確認格擋 →</button><button class="text-btn wide" data-action="clear-blocks" ${!mine()?'disabled':''}>清空自由格擋</button>`;
 else{if(g.phase==='main'&&!g.stack.length&&(g.tokens?.[seat]??(g.attacker===seat&&g.token)))actions+=`<button class="${attackMode?'primary':'secondary'} wide" data-action="attack" ${!mine()||!g.players[seat].board.length?'disabled':''}>${attackMode?'確認攻擊 · '+attackers.size:'⚔ 選擇攻擊單位'}</button>`;actions+=`<button class="${c?'secondary':'primary'} wide" data-action="pass" ${!mine()?'disabled':''}>${g.stack.length?'讓過 · 等待法術結算':g.phase==='combat'?'讓過 · 準備戰鬥':g.passes?'讓過 · 結束本輪':'讓過行動'} →</button>`;}
 }
 return `<aside class="action-panel"><div class="turn-status"><i class="${mine()?'active':''}"></i>${!ready?'等待另一位玩家':g.winner!==null?'本局結束':mine()?'輪到你行動':'等待對手行動'}</div>${room?`<button class="room-code mobile-room" data-action="copy-room">${room.code}<small>點擊複製房間碼</small></button>`:''}<div class="phase-heading"><small>第 ${g.round} 輪 · ${mode==='local'?'玩家 '+(seat+1):'你'}</small><h2>${phaseName()}</h2></div><p class="hint">${esc(hint())}</p><div class="detail-area">${detail()}</div><div class="action-buttons">${actions}</div>${netError?`<p class="net-error">${esc(netError)}</p>`:''}</aside>`;
}
function mulliganMarkup(){if(g.phase!=='mulligan'||curtain||!ready||!mine())return '';return `<div class="mulligan-overlay"><section class="mulligan-dialog" role="dialog" aria-modal="true" aria-label="調整起手牌"><div class="eyebrow">YOUR OPENING HAND</div><h2>每一場傳說，從選擇開始。</h2><p>點擊要更換的卡牌，或保留全部。雙方換牌完成後，各抽一張牌開始第 1 輪。</p><div class="mulligan-cards">${g.players[seat].hand.map(h=>`<div class="mulligan-option ${mulligans.has(h.uid)?'replace':''}">${cardMarkup(h,{chosen:mulligans.has(h.uid)})}<span>${mulligans.has(h.uid)?'↻ 更換':'保留'}</span></div>`).join('')}</div><button class="primary" data-action="mulligan">${mulligans.size?'更換 '+mulligans.size+' 張牌':'保留全部起手牌'} →</button></section></div>`;}
function stackMarkup(){return `<div class="spell-stack">${g.stack.length?'<span>回應鏈 · 後進先出</span>'+g.stack.slice().reverse().map((x,i)=>`<button class="stack-item ${selectedTargetIds().includes(x.uid)?'chosen':''} ${mine()&&activeTarget()==='stack'?'targetable':''}" data-stack="${esc(x.uid||'')}" title="${esc(C[x.displayId||x.cid]?.text||'')}">${i+1}. ${esc(C[x.displayId||x.cid]?.name||'技能')}<small>${x.p===seat?'己方':'對手'}</small></button>`).join(''):''}</div>`;}
function manifestMarkup(){if(!g.choice||g.choice.p!==seat||curtain||!ready||!mine())return '';return `<div class="manifest-overlay"><section class="manifest-dialog" role="dialog" aria-modal="true" aria-label="挑選卡牌"><div class="eyebrow">CHOOSE YOUR CARD</div><h2>你的下一個選擇。</h2><p>選擇一張卡牌加入手牌，接著繼續結算。</p><div class="manifest-options">${g.choice.options.map((option,i)=>{const id=typeof option==='string'?option:option.card||option.id;return `<div class="manifest-option">${cardMarkup({card:id},{catalog:true})}<button class="primary" data-choice="${esc(id)}">選擇 ${esc(C[id]?.name||'卡牌')} →</button></div>`;}).join('')}</div></section></div>`;}
function gameScreen(){const opp=1-seat;return `${header()}<main class="game"><aside class="match-panel"><div class="eyebrow">FOUNDATIONS / PVP</div><h2>符文大地的對決</h2><p class="match-type">${mode==='local'?'同屏雙人 · 交替操作':'連線雙人 · 即時同步'}</p>${room?`<button class="room-code" data-action="copy-room">${room.code}<small>點擊複製房間碼</small></button>`:''}<div class="match-divider"></div><div class="log-title">對局紀錄 <span>↙</span></div><div class="battle-log">${g.log.slice(-20).reverse().map((s,i)=>`<div class="${i===0?'latest':''}"><i></i>${esc(s)}</div>`).join('')}</div><button class="text-btn leave" data-action="ask-leave">離開對局 ↗</button></aside><section class="table"><div class="opponent-hand" aria-label="對手手牌 ${g.players[opp].handCount} 張">${Array.from({length:g.players[opp].handCount},()=>'<span>✦</span>').join('')}<small>${g.players[opp].handCount} 張手牌</small></div>${playerBar(opp,true)}${boardRow(opp)}${stackMarkup()}<div class="arena" data-arena>${arena()}</div>${boardRow(seat)}${playerBar(seat,false)}<div class="hand-label">你的手牌 <span>${g.players[seat].handCount} / 10</span><small>${curtain?'等待玩家就位':mine()?'點選或拖曳卡牌開始行動':'等待行動權 · 右鍵查看卡牌'}</small></div><div class="hand">${g.players[seat].hand.map(h=>curtain?'<div class="card back"><span>✦</span></div>':cardMarkup(h,{active:selected===h.uid,targetable:handTargetable(h),chosen:targetSelected(h.uid)})).join('')}</div></section>${actionPanel()}</main>${curtain?`<div class="curtain"><div class="handover-mark">✦</div><div class="eyebrow">PASS THE DEVICE</div><h2>請交給玩家 ${seat+1}</h2><p>${esc(playerName(seat))} · 確認另一位玩家已移開視線，再查看手牌。</p><button class="primary" data-action="reveal">我已就位，查看牌桌 →</button></div>`:''}${mulliganMarkup()}${manifestMarkup()}`;}
function filteredCards(builder=false){return collection.filter(([id,c])=>(!regionFilter||(c.regions||[c.region]).includes(regionFilter))&&(!builder||cardSupported(id))&&(supportFilter!=='supported'||cardSupported(id))&&(supportFilter!=='planned'||!cardSupported(id))&&(!query||[c.name,c.nameEn,id,clean(c.text)].some(x=>String(x).toLowerCase().includes(query.toLowerCase())))).sort((a,b)=>a[1].cost-b[1].cost||a[1].name.localeCompare(b[1].name));}
function filters(builder=false){return `<div class="collection-filters"><label class="search-label">⌕<input id="catalog-query" placeholder="搜尋卡名、效果或卡牌代碼" value="${esc(query)}" aria-label="搜尋卡牌"></label><select id="catalog-region" aria-label="篩選地區"><option value="">所有地區</option>${regions.map(r=>`<option value="${esc(r.id)}" ${regionFilter===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select>${!builder?`<select id="catalog-support" aria-label="篩選實現狀態"><option value="all" ${supportFilter==='all'?'selected':''}>全部卡牌</option><option value="supported" ${supportFilter==='supported'?'selected':''}>已實現 · 可對戰</option><option value="planned" ${supportFilter==='planned'?'selected':''}>待實現</option></select>`:''}</div>`;}
function deckIssues(deck){const issues=[],count={};for(const id of deck)count[id]=(count[id]||0)+1;const rr=new Set(deck.map(id=>C[id]?.region).filter(Boolean));if(deck.length!==40)issues.push(`需要 40 張牌，目前 ${deck.length} 張`);if(Object.values(count).some(x=>x>3))issues.push('同名卡牌最多 3 張');if(deck.filter(id=>C[id]?.hero).length>6)issues.push('英雄卡最多 6 張');if(rr.size>2)issues.push('最多選擇 2 個地區');if(deck.some(id=>!C[id]?.collectible||!cardSupported(id)))issues.push('有卡牌尚未實現');return issues;}
function builderList(){const count={};for(const id of builderDeck)count[id]=(count[id]||0)+1;return Object.entries(count).sort((a,b)=>C[a[0]].cost-C[b[0]].cost||C[a[0]].name.localeCompare(C[b[0]].name)).map(([id,n])=>`<div class="deck-row"><button class="deck-row-title" data-inspect="${esc(id)}"><b>${C[id].cost}</b><span>${C[id].hero?'✦ ':''}${esc(C[id].name)}</span></button><button data-remove="${esc(id)}" aria-label="移除${esc(C[id].name)}">−</button><strong>${n}</strong><button data-add="${esc(id)}" aria-label="加入${esc(C[id].name)}" ${n>=3?'disabled':''}>+</button></div>`).join('')||'<p class="empty-deck">從左側卡牌開始加入，<br>或先載入一套預組套牌。</p>';}
function catalogContent(builder=false){const shown=filteredCards(builder),count={};for(const id of builderDeck)count[id]=(count[id]||0)+1;const cards=`<div class="catalog-results"><span>顯示 ${shown.length} 張</span><span>${builder?'僅顯示已實現的可收藏卡牌':'已實現 '+implemented.length+' / '+collection.length+' 張 · 點擊查看原卡'}</span></div><div class="catalog-grid">${shown.map(([id])=>`<div class="collection-card">${cardMarkup({card:id},{catalog:true})}${builder?`<button class="add-card ${count[id]?'in-deck':''}" data-add="${esc(id)}" ${(count[id]||0)>=3?'disabled':''}>${count[id]?(count[id]+' / 3　＋'):'加入套牌 ＋'}</button>`:''}</div>`).join('')||'<p class="empty-results">沒有符合條件的卡牌。</p>'}</div>`;
 if(!builder)return `<div class="modal-eyebrow">ORIGINAL CARD COLLECTION</div><h2>基礎卡牌圖鑑</h2><p>原版卡名、規則文字與插畫。可對戰標記代表本原型已實現該卡；其餘卡牌保留於圖鑑。</p>${filters()}${cards}`;
 const heroes=builderDeck.filter(id=>C[id]?.hero).length,rr=[...new Set(builderDeck.map(id=>C[id]?.region).filter(Boolean))],issues=deckIssues(builderDeck);
 return `<div class="modal-eyebrow">BUILD YOUR DECK</div><h2>組建你的基礎套牌</h2><p>40 張牌 · 同名最多 3 張 · 英雄最多 6 張 · 最多 2 個地區</p><div class="builder-layout"><div class="builder-collection">${filters(true)}${cards}</div><aside class="deck-builder-panel"><input id="deck-name" value="${esc(builderName)}" maxlength="24" aria-label="套牌名稱"><div class="deck-count ${builderDeck.length===40?'complete':''}"><strong>${builderDeck.length}<small> / 40</small></strong><span>英雄 ${heroes} / 6</span></div><div class="deck-regions">${rr.map(regionName).map(esc).join(' · ')||'尚未選擇地區'}</div><div class="builder-load"><select id="builder-preset" aria-label="載入預組套牌"><option value="">載入預組套牌…</option>${presets.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select><button class="text-btn" data-action="clear-deck">清空</button></div><div class="deck-list">${builderList()}</div><div class="deck-errors">${esc(builderError||issues[0]||'套牌符合規則，可以儲存。')}</div><button class="primary wide" data-action="save-deck" ${issues.length?'disabled':''}>儲存並使用套牌 →</button></aside></div>`;
}
function inspectContent(){const c=C[inspectId];if(!c)return '';return `<div class="inspect-layout"><div class="original-card-image">${c.render?`<img src="${esc(c.render)}" alt="${esc(c.name)}原版完整卡牌" onerror="this.remove()">`:''}<div class="image-fallback">${cardMarkup({card:inspectId},{catalog:true})}</div></div><div class="inspect-copy"><div class="modal-eyebrow">${esc(inspectId)} · ${c.collectible?'可收藏':'衍生卡牌'}</div><h2>${esc(c.name)}</h2><p class="english-name">${esc(c.nameEn)}</p><div class="inspect-tags"><span>${(c.regions||[c.region]).map(regionName).map(esc).join(' · ')}</span><span>${c.cost} 費</span><span>${c.hero?'英雄':c.kind==='unit'?'單位':S[c.speed]||'技能'}</span></div><p>${esc(clean(c.text)||'沒有額外效果。')}</p>${c.levelText?'<p><strong class="gold">升級條件</strong><br>'+esc(clean(c.levelText))+'</p>':''}<div class="implementation-note ${cardSupported(inspectId)?'yes':''}">${cardSupported(inspectId)?'✓ 本原型已實現，可加入套牌':'◷ 規則待實現，目前僅供圖鑑查看'}</div><p class="asset-credit">原版卡牌資料與插畫來自 Riot Data Dragon。此專案為非官方研究原型。</p>${(c.associated||[]).filter(id=>C[id]).length?'<div class="associated"><strong>關聯卡牌</strong><div>'+c.associated.filter(id=>C[id]).map(id=>`<button class="text-btn" data-inspect="${esc(id)}">${esc(C[id].name)} ↗</button>`).join('')+'</div></div>':''}${backModal?'<button class="secondary" data-action="back-collection">← 返回'+(backModal==='deckbuilder'?'組牌':'圖鑑')+'</button>':''}</div></div>`;}
function modalMarkup(){if(!modal)return '';let content='';if(modal==='catalog'||modal==='deckbuilder')content=catalogContent(modal==='deckbuilder');else if(modal==='inspect')content=inspectContent();else if(modal==='leave')content='<h2>離開目前對局？</h2><p>目前對局保存在此分頁，可從大廳繼續。同屏對局會保留到開始新的一局。</p><button class="primary" data-action="leave">返回大廳</button>';else content=`<div class="modal-eyebrow">FIELD GUIDE</div><h2>在符文大地，輪到你出牌。</h2><div class="rules-grid"><section><b>01 / 起手與換牌</b><p>雙方主堡各 20 生命，起手 4 張。選擇要更換的卡牌；換牌完成後，第一輪雙方各抽 1 張。每輪增加法力上限，最多 10 點。</p></section><section><b>02 / 交替行動</b><p>召喚單位與施放慢速法術會交出行動權；疾速法術立即結算，保留行動權。雙方連續讓過、且沒有待結算的戰鬥或法術時，進入下一輪。</p></section><section><b>03 / 法術法力與速度</b><p>輪末剩餘法力存為法術法力，最多 3 點。慢速法術僅能在主階段空白回應鏈施放；快速法術可以回應；疾速法術立即生效。法術法力不能支付單位。</p></section><section><b>04 / 攻擊與格擋</b><p>每輪交替持有攻擊令牌。選擇攻擊者後確認攻擊；防守方點選己方單位，再點戰線分配格擋。格擋時也可施放快速或疾速法術。若防守方加入法術或有待結算技能，攻擊方可以回應；否則確認格擋後直接結算戰鬥。</p></section><section><b>05 / 挑戰者與關鍵字</b><p>選取挑戰者作為攻擊者後，再次點擊它，接著點擊敵軍，可指定它的格擋者。隱密、快速攻擊、碾壓、屏障、吸血、威吓等關鍵字依對應卡牌運作。右鍵卡牌查看原始文字。</p></section><section><b>06 / 套牌與勝負</b><p>每副套牌 40 張，同名最多 3 張、英雄最多 6 張、最多 2 個地區。主堡生命歸零或無法抽牌時落敗。英雄各自依原版卡牌的條件升級。</p></section></div><p class="rules-note">基礎卡池採用 Riot Data Dragon ${esc(DATASET.dataVersion||DATASET.version||'')} 的卡牌資料。目前 ${implemented.length} / ${collection.length} 張可收藏卡牌可用於對戰。圖鑑提供完整卡牌與實現狀態；本原型持續完善規則，不宣稱完整重現官方客戶端。</p>`;
 const label=modal==='deckbuilder'?'組建套牌':modal==='catalog'?'卡牌圖鑑':modal==='inspect'?'原版卡牌詳情':modal==='leave'?'離開對局':'玩法指南';
 return `<div class="modal-backdrop"><section class="modal ${modal==='catalog'?'catalog':modal==='deckbuilder'?'builder-modal':modal==='inspect'?'inspect-modal':''}" role="dialog" aria-modal="true" aria-label="${label}"><button class="close" data-action="close" aria-label="關閉">×</button>${content}</section></div>`;
}
function render(){
 drag.cancel();motion.capture(renderedFrame?.game,renderedFrame||{});
 app.innerHTML=(mode==='lobby'?lobby():gameScreen())+modalMarkup();
 const frame={game:g,seat,curtain,mode,sessionKey:mode+':'+sessionEpoch+':'+(room?.code||'local')};
 const playback=motion.play(g,frame).catch(()=>motion.reset());renderedFrame=frame;return playback;
}

function resetSelection(){selected=null;fixedTargets=[];extraTargets=[];targetGroup=0;replaceUid=null;sacrifices.clear();playChoice='attack';discards.clear();attackMode=false;attackers.clear();challenger=null;challenges={};blocker=null;blocks={};mulligans.clear();}
function localSnapshot(raw){const saved=JSON.parse(raw);if(saved?.schema!==3||saved.players?.length!==2||![0,1].includes(saved.priority))throw new Error('這是舊版本或無效的對局，請開始新局。');return saved;}
function persist(){if(mode==='local')sessionStorage.setItem(STORE+'-local',JSON.stringify(full));if(mode==='online'&&room)sessionStorage.setItem(STORE+'-room',JSON.stringify(room));}
function localStart(){sessionEpoch++;busy=false;try{full=createGame(Math.random,{decks:[chosenDeck(0),chosenDeck(1)],names:[chosenName(0),chosenName(1)]});mode='local';seat=full.priority;g=view(full,seat);curtain=true;ready=true;room=null;resetSelection();persist();render();}catch(e){toast(e.message);}}
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json',...(room?.token?{Authorization:'Bearer '+room.token}:{})},...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await r.json();}catch{throw new Error('無法連接房間服務，請稍後重試');}if(!r.ok)throw new Error(data.error||'請求失敗');return data;}
function accept(data){g=data.game;seat=data.seat;ready=data.ready;mode='online';curtain=false;room={code:data.code,token:data.token||room?.token};netError='';persist();}
async function connect(joinCode){if(busy)return;const epoch=++sessionEpoch;busy=true;try{const data=await api(joinCode?'/api/join':'/api/rooms',joinCode?{code:joinCode,deck:chosenDeck(0)}:{deck:chosenDeck(0)});if(epoch!==sessionEpoch)return;accept(data);resetSelection();}catch(e){if(epoch===sessionEpoch)toast(e.message);}finally{if(epoch===sessionEpoch){busy=false;render();}}}
async function dispatch(a){if(!mine())return;const epoch=sessionEpoch;const preserveBlocks=g.phase==='block'&&a.type==='play',savedBlocks={...blocks};busy=true;try{if(mode==='local'){const old=seat;full=act(full,seat,a);const nextSeat=full.priority;g=view(full,old);curtain=false;resetSelection();persist();if(nextSeat!==old&&full.winner===null){await render();if(epoch!==sessionEpoch||mode!=='local')return;seat=nextSeat;g=view(full,seat);curtain=true;}else{seat=nextSeat;g=view(full,seat);}}else{const d=await api('/api/action',{code:room.code,version:g.version,action:a});if(epoch!==sessionEpoch||mode!=='online')return;accept(d);}resetSelection();if(preserveBlocks&&g.phase==='block'){blocks=Object.fromEntries(Object.entries(savedBlocks).filter(([a,b])=>g.combat.lanes.some(l=>l.attacker===a)&&g.players[seat].board.some(u=>u.uid===b)));}}catch(e){toast(e.message);}finally{if(epoch===sessionEpoch){busy=false;render();}}}
async function poll(){if(mode!=='online'||!room||busy||polling)return;polling=true;const epoch=sessionEpoch,code=room.code,token=room.token;try{const data=await api('/api/rooms/'+code);if(mode!=='online'||epoch!==sessionEpoch||room?.code!==code||room?.token!==token||data.game.version<g.version||ready&&!data.ready)return;const changed=!g||data.game.version!==g.version||data.ready!==ready||netError;if(changed){accept(data);resetSelection();render();}}catch(e){if(epoch===sessionEpoch&&mode==='online'&&netError!==e.message){netError=e.message;render();}}finally{polling=false;}}
function doPlay(){const h=selectedCard();if(!h||!mine()||g.choice)return;if(discardSpec()&&(discards.size<discardCount()||discards.size>discardSpec().max)){toast('請選擇 '+discardCount()+' 張要棄置的手牌');return;}if(!targetReady()){toast('請完成目標與犧牲代價的選擇');return;}dispatch({type:'play',uid:h.uid,target:fixedTargets[0]||null,target2:fixedTargets[1]||null,target3:fixedTargets[2]||null,targets:[...extraTargets],replace:replaceUid,sacrifices:[...sacrifices],choice:playChoice,discards:[...discards]});}
// Pointer gestures feed the same selection and action path as click controls.
// The server remains the only authority on legality and final resolution.
function playableHand(h){
 const c=C[h.card],s=g.players[seat];if(!c)return false;
 if(c.kind==='unit')return g.phase==='main'&&!g.stack.length&&s.mana>=(h.cost??c.cost);
 if(['slow','focus'].includes(c.speed)&&(g.phase!=='main'||g.stack.length))return false;
 return s.mana+s.bank>=(h.cost??c.cost);
}
function uiBlockLegal(attacker,defender){
 const a=keywords(attacker,g),b=keywords(defender,g);
 return !defender.stunned&&!b.includes('CantBlock')&&!b.includes('Immobile')&&(!a.includes('Elusive')||b.includes('Elusive')||b.includes('Sharpsight'))&&(!a.includes('Fearsome')||attack(defender,g)>=3)&&!(attack(defender,g)===0&&g.players[1-seat].board.some(u=>C[u.card].nameEn==='Ashe'&&u.level&&!u.silenced));
}
function canDrop(source,drop){
 if(!mine()||modal||g.choice||g.phase==='mulligan'||!drop)return false;
 const own=g.players[seat];
 if(source.kind==='hand'){
  const h=own.hand.find(h=>h.uid===source.uid);if(!h||!playableHand(h))return false;const c=C[h.card];
  if(drop.kind==='board')return drop.p===seat;
  if(drop.kind==='arena')return c.kind==='spell';
  const type=selected===h.uid?activeTarget():(c.targets||[c.target,c.target2,c.target3]).find(type=>type&&type!=='none')||c.targetCount?.type;
  if(drop.kind==='stack')return type==='stack'&&g.stack.some(x=>x.uid===drop.uid);
  if(drop.kind==='hand')return ['allyHand','cardHand','allyHandUnit'].includes(type)&&drop.uid!==h.uid&&own.hand.some(t=>t.uid===drop.uid&&(type!=='allyHandUnit'||C[t.card].kind==='unit'));
  if(drop.kind==='core')return targetAllowed(type,drop.p,null,true);
  if(drop.kind==='unit'){const u=g.players[drop.p]?.board.find(u=>u.uid===drop.uid);return !!u&&targetAllowed(type,drop.p,u);}
  return false;
 }
 const u=own.board.find(u=>u.uid===source.uid);if(!u)return false;
 if(g.phase==='block'){
  const aid=drop.kind==='lane'?drop.uid:drop.kind==='unit'&&drop.p!==seat?drop.uid:null,lane=g.combat?.lanes.find(l=>l.attacker===aid),a=g.players[1-seat].board.find(u=>u.uid===aid);
  return !!lane&&!lane.challenged&&!!a&&uiBlockLegal(a,u);
 }
 if(g.phase!=='main'||g.stack.length||!g.tokens?.[seat]||u.stunned||keywords(u,g).includes('Immobile'))return false;
 if(drop.kind==='arena')return true;
 if(drop.kind==='unit'&&drop.p!==seat&&keywords(u,g).includes('Challenger')){const enemy=g.players[drop.p].board.find(x=>x.uid===drop.uid);return !!enemy&&!enemy.stunned&&!keywords(enemy,g).includes('CantBlock');}
 return false;
}
function handleDrop(intent){
 if(!canDrop(intent,intent.drop))return;const {uid,kind,drop}=intent;
 if(kind==='hand'){
  if(selected!==uid){resetSelection();selected=uid;playChoice=C[selectedCard()?.card]?.options?.[0]?.id||'attack';}
  if(['unit','core','hand','stack'].includes(drop.kind)){pickTarget(drop.kind==='core'?'core'+drop.p:drop.uid);}
  else render();
  const c=C[selectedCard()?.card];
  if(c&&!targetPlan().length&&!discardSpec()&&!sacrificeCount()&&!c.options&&!replacementNeeded())doPlay();
  return;
 }
 if(g.phase==='block'){
  const aid=drop.uid;for(const id of Object.keys(blocks))if(blocks[id]===uid)delete blocks[id];blocks[aid]=uid;blocker=null;render();return;
 }
 if(!attackMode){resetSelection();attackMode=true;}selected=null;attackers.add(uid);
 if(drop.kind==='unit'&&drop.p!==seat){for(const id of Object.keys(challenges))if(challenges[id]===drop.uid)delete challenges[id];challenges[uid]=drop.uid;}
 render();
}
function openBuilder(){builderDeck=[...(customDeck?.deck||chosenDeck(0))];builderName=customDeck?.name||'我的基礎套牌';builderError='';query='';regionFilter='';supportFilter='all';modal='deckbuilder';render();}
function inspect(id){if(!C[id])return;backModal=['catalog','deckbuilder'].includes(modal)?modal:modal==='inspect'?backModal:null;inspectId=id;modal='inspect';render();}
function addToDeck(id){const c=C[id];if(!c?.collectible||!cardSupported(id))return;if(builderDeck.length>=40){toast('套牌已滿 40 張');return;}if(builderDeck.filter(x=>x===id).length>=3){toast('同名卡牌最多 3 張');return;}if(c.hero&&builderDeck.filter(x=>C[x].hero).length>=6){toast('英雄卡最多 6 張');return;}const rr=new Set([...builderDeck.map(x=>C[x].region),c.region].filter(Boolean));if(rr.size>2){toast('套牌最多 2 個地區');return;}builderDeck.push(id);builderError='';render();}
function preserveSearchRender(){const start=$('#catalog-query')?.selectionStart;render();const el=$('#catalog-query');if(el){el.focus();el.setSelectionRange(start,start);}}
app.addEventListener('input',e=>{if(e.target.id==='catalog-query'){query=e.target.value;preserveSearchRender();}if(e.target.id==='deck-name')builderName=e.target.value;});
app.addEventListener('change',e=>{if(e.target.matches('[data-deck-seat]')){deckChoices[Number(e.target.dataset.deckSeat)]=e.target.value;return;}if(e.target.id==='catalog-region'){regionFilter=e.target.value;render();}if(e.target.id==='catalog-support'){supportFilter=e.target.value;render();}if(e.target.id==='play-choice')playChoice=e.target.value;if(e.target.id==='builder-preset'&&e.target.value){const p=presets.find(x=>x.id===e.target.value);builderDeck=[...p.deck];builderName=p.name;builderError='';render();}});
app.addEventListener('submit',e=>{if(e.target.id==='join-form'){e.preventDefault();const code=$('#room-code').value.trim().toUpperCase();if(code.length!==8){toast('請輸入 8 位房間碼');return;}connect(code);}});
app.addEventListener('click',async e=>{
 if(e.target.closest('[data-action="motion"]')){reducedMotion=!reducedMotion;try{localStorage.setItem(STORE+'-motion',reducedMotion?'reduced':'full');}catch{}motion.setReduced(reducedMotion);render();return;}
 const choose=e.target.closest('[data-choice]');if(choose&&g?.choice?.p===seat){dispatch({type:'choose',choice:choose.dataset.choice});return;}
 const replaceMode=e.target.closest('[data-replace-mode]');if(replaceMode){targetGroup=-1;render();return;}
 const removeReplace=e.target.closest('[data-remove-replace]');if(removeReplace){replaceUid=null;render();return;}
 const selfTarget=e.target.closest('[data-self-target]');if(selfTarget){pickTarget(selected);return;}
 const group=e.target.closest('[data-target-group]');if(group){targetGroup=Number(group.dataset.targetGroup);render();return;}
 const removeTarget=e.target.closest('[data-remove-target]');if(removeTarget){const n=Number(removeTarget.dataset.removeGroup),group=targetPlan()[n];if(group?.fixed)fixedTargets[group.slot]=null;else extraTargets=extraTargets.filter(x=>x!==removeTarget.dataset.removeTarget);targetGroup=n;render();return;}
 const removeSacrifice=e.target.closest('[data-remove-sacrifice]');if(removeSacrifice){sacrifices.delete(removeSacrifice.dataset.removeSacrifice);render();return;}
 const stack=e.target.closest('[data-stack]');if(stack&&mine()&&activeTarget()==='stack'&&stack.dataset.stack){pickTarget(stack.dataset.stack);return;}
 const add=e.target.closest('[data-add]');if(add){addToDeck(add.dataset.add);return;}
 const remove=e.target.closest('[data-remove]');if(remove){const i=builderDeck.indexOf(remove.dataset.remove);if(i>=0)builderDeck.splice(i,1);builderError='';render();return;}
 const inspectButton=e.target.closest('[data-inspect]');if(inspectButton){inspect(inspectButton.dataset.inspect);return;}
 const button=e.target.closest('[data-action]');if(button){const a=button.dataset.action;
  if(a==='catalog'){modal='catalog';query='';regionFilter='';supportFilter='all';render();}
  else if(a==='rules'){modal=a;render();}
  else if(a==='deckbuilder')openBuilder();
  else if(a==='close'){modal=null;backModal=null;render();}
  else if(a==='back-collection'){modal=backModal;backModal=null;render();}
  else if(a==='clear-deck'){builderDeck=[];builderError='';render();}
  else if(a==='save-deck'){const issues=deckIssues(builderDeck);if(issues.length){builderError=issues[0];render();return;}customDeck={name:builderName.trim()||'我的基礎套牌',deck:[...builderDeck]};localStorage.setItem('et-deck',JSON.stringify(customDeck));deckChoices[0]='custom';modal=null;render();toast('套牌已儲存並設為玩家一套牌');}
  else if(a==='local')localStart();
  else if(a==='create')connect();
  else if(a==='home'){if(mode!=='lobby'){modal='leave';render();}}
  else if(a==='ask-leave'){modal='leave';render();}
  else if(a==='leave'){sessionEpoch++;busy=false;mode='lobby';modal=null;curtain=false;render();}
  else if(a==='resume-local'){sessionEpoch++;busy=false;try{full=localSnapshot(sessionStorage.getItem(STORE+'-local'));g=view(full,full.priority);seat=full.priority;mode='local';ready=true;room=null;curtain=full.winner===null;resetSelection();render();}catch(err){toast(err.message||'無法恢復此對局，請開始新局');}}
  else if(a==='resume-online'){const epoch=++sessionEpoch;busy=true;try{room=JSON.parse(sessionStorage.getItem(STORE+'-room'));const data=await api('/api/rooms/'+room.code);if(epoch!==sessionEpoch)return;accept(data);resetSelection();}catch(err){if(epoch===sessionEpoch)toast(err.message);}finally{if(epoch===sessionEpoch){busy=false;render();}}}
  else if(a==='reveal'){curtain=false;render();}
  else if(a==='pass')dispatch({type:'pass'});
  else if(a==='mulligan')dispatch({type:'mulligan',cards:[...mulligans]});
  else if(a==='play')doPlay();
  else if(a==='cancel'){resetSelection();render();}
  else if(a==='attack'){selected=null;fixedTargets=[];extraTargets=[];targetGroup=0;replaceUid=null;sacrifices.clear();if(!attackMode){attackMode=true;render();}else if(!attackers.size)toast('請至少選擇一個攻擊單位');else dispatch({type:'attack',units:[...attackers],challenges});}
  else if(a==='block')dispatch({type:'block',assignments:blocks});
  else if(a==='clear-blocks'){blocks={};blocker=null;render();}
  else if(a==='copy-room'){try{await navigator.clipboard.writeText(room.code);toast('房間碼已複製');}catch{toast('房間碼：'+room.code);}}
  return;
 }
 const h=e.target.closest('[data-hand]');if(h&&mode!=='lobby'&&!modal){if(g.phase==='mulligan'&&mine()){mulligans.has(h.dataset.hand)?mulligans.delete(h.dataset.hand):mulligans.add(h.dataset.hand);render();return;}if(mine()&&selected&&h.dataset.hand===selected&&activeGroup()?.includeSelf){pickTarget(selected);return;}if(mine()&&selected&&h.dataset.hand!==selected){if(discardSpec()){if(discards.has(h.dataset.hand))discards.delete(h.dataset.hand);else if(discards.size<discardSpec().max)discards.add(h.dataset.hand);else toast('已選足棄置手牌');render();return;}if(handTargetable(g.players[seat].hand.find(x=>x.uid===h.dataset.hand))){pickTarget(h.dataset.hand);return;}}selected=selected===h.dataset.hand?null:h.dataset.hand;fixedTargets=[];extraTargets=[];targetGroup=0;replaceUid=null;sacrifices.clear();discards.clear();playChoice=C[selectedCard()?.card]?.options?.[0]?.id||'attack';attackMode=false;attackers.clear();challenger=null;challenges={};render();return;}
 const core=e.target.closest('[data-core]');if(core&&canTarget(Number(core.dataset.core),null,true)){pickTarget('core'+core.dataset.core);return;}
 const unitButton=e.target.closest('[data-unit]');if(unitButton&&g){const id=unitButton.dataset.unit,p=g.players.findIndex(s=>s.board.some(x=>x.uid===id));if(p<0)return;const unit=g.players[p].board.find(x=>x.uid===id);if(canTarget(p,unit)){pickTarget(id);return;}if(mine()&&attackMode&&p!==seat&&challenger){for(const a of Object.keys(challenges))if(challenges[a]===id)delete challenges[a];challenges[challenger]=id;challenger=null;render();return;}if(mine()&&p===seat){if(attackMode){if(unit.stunned){toast('被擊暈的單位無法攻擊');return;}if(!attackers.has(id)){attackers.add(id);challenger=null;}else if(keywords(unit,g).includes('Challenger')&&challenger!==id){challenger=id;}else{attackers.delete(id);delete challenges[id];challenger=null;}render();}else if(g.phase==='block'){blocker=blocker===id?null:id;render();}else inspect(unit.card);}else inspect(unit.card);return;}
 const lane=e.target.closest('[data-lane]');if(lane&&mine()&&g.phase==='block'){const id=lane.dataset.lane;if(blocker){for(const a of Object.keys(blocks))if(blocks[a]===blocker)delete blocks[a];blocks[id]=blocker;blocker=null;}else delete blocks[id];render();}
});
app.addEventListener('contextmenu',e=>{const card=e.target.closest('[data-hand],[data-unit]');if(!card||!g||curtain)return;e.preventDefault();const id=card.dataset.hand||card.dataset.unit,all=g.players.flatMap(s=>[...s.hand,...s.board]),h=all.find(x=>x.uid===id);if(h?.card)inspect(h.card);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(modal==='inspect'&&backModal){modal=backModal;backModal=null;}else modal=null;resetSelection();render();}});
render();setInterval(poll,1400);
